import * as React from 'react';
import { barClasses } from '@mui/x-charts/BarChart';
import {
  BarChartPremium,
  rangeBarClasses,
  RangeBarSeries,
} from '@mui/x-charts-premium/BarChartPremium';

const settings = {
  xAxis: [{ data: ['group A', 'group B', 'group C'] }],
  series: [
    {
      type: 'rangeBar',
      id: '1',
      data: [
        [4, 3],
        [5, 8],
        [2, 4],
      ],
    },
    {
      type: 'rangeBar',
      id: '2',
      data: [
        [1, 6],
        [5, 6],
        [3, 9],
      ],
    },
    {
      type: 'rangeBar',
      id: '3',
      data: [
        [1, 5],
        [2, 4],
        [3, 8],
      ],
    },
  ] satisfies RangeBarSeries[],
  height: 300,
  margin: { left: 0 },
} as const;

export default function RangeBarGradient() {
  return (
    <BarChartPremium
      {...settings}
      sx={{
        [`& .${rangeBarClasses.series}[data-series="2"] .${barClasses.element}`]: {
          fill: 'url(#bar-gradient)',
        },
      }}
